"""Resolve a logical training record to its backing file."""

import json
from pathlib import Path


def resolve(root, record):
    catalog_path = root / 'catalog.json'
    with open(catalog_path) as f:
        catalog = json.load(f)

    record_sha256 = record.get('sha256')
    if not record_sha256:
        raise ValueError('Record missing required sha256 field')

    for row in catalog['rows']:
        if row['sha256'] == record_sha256:
            return row['path']

    raise FileNotFoundError(f'No file found with sha256 {record_sha256}')

